// Parse Kitchen Command from WhatsApp Number B
const body = $input.item.json.body || $input.item.json;
let rawText = '';
let senderPhone = '';

if (body.entry && body.entry[0]?.changes && body.entry[0].changes[0]?.value?.messages) {
  const msg = body.entry[0].changes[0].value.messages[0];
  if (msg.type === 'text') rawText = msg.text.body.trim();
  else if (msg.type === 'interactive') rawText = msg.interactive.button_reply?.id || '';
  senderPhone = msg.from;
} else if (body.text || body.message) {
  rawText = (body.text || body.message).trim();
  senderPhone = body.phone || 'kitchen';
}

// Regex matching commands:
// Examples: "STATUS ORD-1042 PREPARING", "CONFIRM ORD-1042", "OUT ORD-1042", "DELIVERED ORD-1042"
const match = rawText.match(/(?:STATUS\s+)?(ORD-\d{4})\s+(PREPARING|CONFIRMED|OUT|DELIVERED|CANCEL)/i) ||
              rawText.match(/(CONFIRM|PREPARING|OUT|DELIVERED|CANCEL)\s+(ORD-\d{4})/i);

if (!match) {
  return [{
    json: {
      is_valid_command: false,
      rawText: rawText,
      senderPhone: senderPhone,
      message: "Invalid kitchen command. Format: 'STATUS ORD-XXXX PREPARING' or 'OUT ORD-XXXX'"
    }
  }];
}

let orderNumber = '';
let action = '';

if (match[1].startsWith('ORD-')) {
  orderNumber = match[1].toUpperCase();
  action = match[2].toUpperCase();
} else {
  action = match[1].toUpperCase();
  orderNumber = match[2].toUpperCase();
}

let newStatus = 'preparing';
let customerNotification = '';

switch(action) {
  case 'CONFIRM':
  case 'CONFIRMED':
    newStatus = 'confirmed';
    customerNotification = '✅ *Order Confirmed!* Kitchen ne aapka order accept kar liya hai.';
    break;
  case 'PREPARING':
    newStatus = 'preparing';
    customerNotification = '🍳 *Cooking Now!* Chef aapka fresh khana tayyar kar rahe hain.';
    break;
  case 'OUT':
  case 'DISPATCH':
  case 'DISPATCHED':
    newStatus = 'out_for_delivery';
    customerNotification = '🛵 *Out for Delivery!* Rider aapka garma-garam order le kar nikal chuka hai. Jald pohonch raha hai!';
    break;
  case 'DELIVERED':
    newStatus = 'delivered';
    customerNotification = '🎉 *Delivered!* Aapka order deliver ho chuka hai. Umeed hai khana pasand aayega!';
    break;
  case 'CANCEL':
  case 'CANCELLED':
    newStatus = 'cancelled';
    customerNotification = '⚠️ *Order Cancelled*: Kisi majboori ke tehat kitchen se aapka order cancel kiya gaya hai.';
    break;
}

return [{
  json: {
    is_valid_command: true,
    order_number: orderNumber,
    new_status: newStatus,
    customer_notification: customerNotification,
    kitchen_phone: senderPhone
  }
}];

